def _merge_plea_kind_into_todo(
    db: Any,
    todo: Dict[str, object],
    *,
    breach_kind: str,
    reason: str,
    target_dossier_id: int,
    extra: Optional[Dict[str, object]],
) -> int:
    """同回合第二类松手：显式并入既有 pending，log+meta 记全被吞类。"""
    meta = decode_plea_meta(todo.get("origin_context"))
    primary = str(meta.get("breach_kind") or "")
    absorbed = meta.get("absorbed_breach_kinds")
    if not isinstance(absorbed, list):
        absorbed = []
    absorbed_list = [str(x) for x in absorbed if str(x or "").strip()]
    kind = str(breach_kind or "").strip()
    if kind and kind != primary and kind not in absorbed_list:
        absorbed_list.append(kind)
        logger.info(
            "breach_plea merge: commitment=%s turn_todo=%s primary=%s absorbed+=%s",
            todo.get("commitment_ref"), todo.get("id"), primary, kind,
        )
    meta["absorbed_breach_kinds"] = absorbed_list
    # 保留首类 primary；补充理由/案卷
    if reason and not str(meta.get("reason") or "").strip():
        meta["reason"] = str(reason)
    elif reason:
        prev = str(meta.get("reason") or "")
        add = str(reason)
        if add and add not in prev:
            meta["reason"] = f"{prev}；{add}"
    if int(target_dossier_id or 0) > 0 and int(meta.get("target_dossier_id") or 0) <= 0:
        meta["target_dossier_id"] = int(target_dossier_id)
    if extra:
        for k, v in extra.items():
            if k not in meta:
                meta[k] = v
    encoded = encode_plea_meta(meta)
    db.conn.execute(
        "UPDATE next_audience_todos SET origin_context=? WHERE id=?",
        (encoded, int(todo["id"])),
    )
    # criterion 保持首类标签；多类痕迹在 meta
    return int(todo["id"])

def _merge_underscore_control_keys(
    existing_json: object, new_payload: Dict[str, object],
) -> Dict[str, object]:
    """把新 payload 与旧 payload 里的下划线控制键（`_` 前缀）合并：新 payload 为主，
    旧的下划线键在新里缺席时保留。用于原地改草不抹夜内态/待澄清闸（#502 L5）。"""
    try:
        old = json.loads(existing_json or "{}") if not isinstance(
            existing_json, (dict, list)) else existing_json
    except (ValueError, TypeError):
        old = {}
    merged: Dict[str, object] = dict(new_payload or {})
    if isinstance(old, dict):
        for k, v in old.items():
            if str(k).startswith("_") and k not in merged:
                merged[k] = v
    return merged

def _dispatch_rushes(
    db: Any,
    state: Any,
    raw: object,
    *,
    minister_name: str,
    source: Provenance,
    source_chat_turn_id: int = 0,
) -> SectionResult:
    """催办声明 → 既有 pending 催办写口（密令 / 分段承诺，ADR 0078）。

    ``source_chat_turn_id``（#1890）：暂存行的来源轮，随交办身份落库。"""
    items, rejected = _section_items(raw, label="催办声明", source=source)
    applied: List[Any] = []
    for item in items:
        target_kind = str(item.get("target_kind") or "").strip()
        try:
            target_id = int(item.get("target_id") or 0)
        except (TypeError, ValueError):
            target_id = 0
        if target_kind not in {"commitment", "secret_order"} or target_id <= 0:
            _reject(
                rejected, item,
                "催办须含 target_kind=commitment|secret_order 与正 target_id",
                "invalid_shape", source,
            )
            continue
        try:
            raw_deadline = item.get("deadline_months", 1)
            deadline = max(0, min(int(raw_deadline if raw_deadline is not None else 1), 36))
        except (TypeError, ValueError):
            deadline = 1
        reason = str(item.get("reason") or "")
        actor = str(minister_name or "").strip() or _commission_fallback_actor(db)
        if target_kind == "commitment":
            row = db.conn.execute(
                "SELECT id, status, stages_json FROM issues WHERE id=?",
                (target_id,),
            ).fetchone()
            if row is None:
                _reject(rejected, item, f"催办目标承诺不存在：{target_id}", "hallucinated_id", source)
                continue
            if str(row["status"] or "") != "active":
                _reject(
                    rejected, item,
                    f"催办目标承诺状态不容许：{row['status']}",
                    "invalid_state", source,
                )
                continue
            try:
                stage_idx = int(item["stage_idx"])
            except (KeyError, TypeError, ValueError):
                _reject(rejected, item, "催办缺目标分段索引", "invalid_shape", source)
                continue
            from ming_sim.staged_commitment import normalize_commitment_stages
            stages = normalize_commitment_stages(row["stages_json"])
            if not any(int(stage["stage_idx"]) == stage_idx for stage in stages):
                _reject(rejected, item, "催办目标分段不存在", "invalid_state", source)
                continue
            payload = {
                "stage_idx": stage_idx,
                "deadline_months": deadline,
                "reason": reason,
