def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

def _sponsor_transferred(db: Any, name: str, commitment_row: Any) -> bool:
    """调：status 仍 active，但职务已变（相对承诺/案卷记录的主办职）。"""
    char = db.conn.execute(
        "SELECT status, office FROM characters WHERE name=?", (name,),
    ).fetchone()
    if char is None:
        return False
    if str(char["status"] or "") != "active":
        return False
    current_office = str(char["office"] or "").strip()
    # character_offices 备档
    co = db.conn.execute(
        "SELECT office_title FROM character_offices WHERE character_name=?",
        (name,),
    ).fetchone()
    if co is not None:
        current_office = str(co["office_title"] or current_office).strip() or current_office

    # 承诺 / 案卷侧只取 office 身份字段；role 是职分自由措辞，不得与 current_office 比语义。
    expected = ""
    try:
        roster = json.loads(commitment_row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        roster = []
    if isinstance(roster, list):
        for item in roster:
            if not isinstance(item, dict):
                continue
            if str(item.get("character_id") or "").strip() != name:
                continue
            if item.get("tier") != "主办":
                continue
            # #1847: no role fallback, no substring/length proxy for "is office".
            expected = str(item.get("office") or item.get("office_title") or "").strip()
            break

    # 案卷 executor office 快照（结构化 office 字段，非自由 role）
    if not expected:
        did = parse_dossier_id(
            commitment_row["origin_ref"] if "origin_ref" in commitment_row.keys() else ""
        )
        if did is not None:
            drow = db.conn.execute(
                "SELECT executor_id, payload_json FROM decree_dossiers WHERE id=?",
                (int(did),),
            ).fetchone()
            if drow is not None and str(drow["executor_id"] or "") == name:
                try:
                    payload = json.loads(drow["payload_json"] or "{}")
                except (TypeError, ValueError):
                    payload = {}
                if isinstance(payload, dict):
                    expected = str(
                        payload.get("executor_office")
                        or payload.get("office")
                        or ""
                    ).strip()

    # office_change_records：有调任记录且当前 office 与承诺侧 office 身份不等
    oc = db.conn.execute(
        """
        SELECT office_title FROM office_change_records
        WHERE character_name=? ORDER BY id DESC LIMIT 1
        """,
        (name,),
    ).fetchone()
    if oc is not None and expected:
        latest = str(oc["office_title"] or "").strip()
        if latest and expected and latest != expected and current_office != expected:
            return True
    # Exact office-identity inequality only — no length/substring free-text classify.
    if expected and current_office and expected != current_office:
        return True
    return False

def _codex_event_text(obj: object) -> str:
    if not isinstance(obj, dict):
        return ""
    typ = str(obj.get("type") or obj.get("event") or "")
    if "delta" in typ:
        for key in ("delta", "content", "text"):
            value = obj.get(key)
            if isinstance(value, str) and value:
                return value
        nested = obj.get("message")
        if isinstance(nested, dict):
            value = nested.get("delta") or nested.get("content") or nested.get("text")
            return value if isinstance(value, str) else ""
    return ""

def _drop_maintenance_column(self) -> None:
    """#173：物理移除退役的 armies.maintenance_per_turn 列（月饷由 army_needed 按兵力派生）。
    幂等：列存在才 DROP（SQLite 3.35+ 支持 ALTER TABLE DROP COLUMN，本仓 3.53）。调用点保证排在
    所有读维护费的迁移之后（见 init_schema：salary_rate backfill + arrears 换算之后）：老档此刻列
    仍在、迁移已读完，drop 安全；新档/已删档无此列，PRAGMA 查不到 → no-op。"""
    cols = {r["name"] for r in self.conn.execute("PRAGMA table_info(armies)").fetchall()}
    if "maintenance_per_turn" in cols:
        self.conn.execute("ALTER TABLE armies DROP COLUMN maintenance_per_turn")
        self.conn.commit()  # DDL 显式提交，保证 drop 跨打开/环境持久（Gemini PR R3；init_schema

def attach_pending_action_endorsement(
    self, action_id: int, entry: Mapping[str, object], *, commit: bool = True,
) -> None:
    """#1842：把本轮背书挂进暂存载荷 endorsements 列表（不造待背书表）。"""
    aid = int(action_id)
    row = self.conn.execute(
        "SELECT payload_json, status FROM pending_actions WHERE id=?",
        (aid,),
    ).fetchone()
    if row is None:
        raise KeyError(f"暂存动作不存在：{aid}")
    if str(row["status"] or "") != "pending":
        raise ValueError(f"暂存动作状态不可挂背书：{row['status']}")
    try:
        payload = json.loads(str(row["payload_json"] or "{}"))
    except (TypeError, ValueError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    form = str(entry.get("form") or "").strip()
    endorser_id = str(entry.get("endorser_id") or "").strip()
    imperial = bool(entry.get("imperial", False))
    source_cid = int(entry.get("source_chat_turn_id") or 0)
    # 暂存阶段尚无 dossier：只验形式/人物/来源轮（与 _validate 同口径）。
    if form == "御笔手敕":
        imperial, endorser_id = True, ""
    if form not in {"会签", "当面站台", "御笔手敕"}:
        raise ValueError("背书形式非法")
    if form == "御笔手敕":
        if not imperial or endorser_id:
            raise ValueError("御笔手敕必须使用御笔标记且不得具名大臣")
    else:
        if imperial or not endorser_id:
            raise ValueError("会签/当面站台必须具名背书人")
        if self.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (endorser_id,),
        ).fetchone() is None:
            raise ValueError("背书人物不存在")
    if source_cid <= 0:
        raise ValueError("背书来源对话轮 id 须为正整数")
    if self.conn.execute(
        "SELECT 1 FROM chat_turns WHERE id=?", (source_cid,),
    ).fetchone() is None:
        raise ValueError("背书来源对话轮不存在")
    items = list(payload.get("endorsements") or [])
    if not isinstance(items, list):
        items = []
    # 同轮同形同人去重（INSERT OR IGNORE 同语义）。
    key = (form, endorser_id, imperial, source_cid)
    kept = []
    for raw in items:
        if not isinstance(raw, Mapping):
            continue
        k = (
            str(raw.get("form") or "").strip(),
            str(raw.get("endorser_id") or "").strip(),
            bool(raw.get("imperial", False)),
            int(raw.get("source_chat_turn_id") or 0),
        )
        if k == key:
            continue
        kept.append(dict(raw))
    kept.append({
        "form": form, "endorser_id": endorser_id,
        "imperial": imperial, "source_chat_turn_id": source_cid,
    })
    payload["endorsements"] = kept
    self.conn.execute(
        "UPDATE pending_actions SET payload_json=? WHERE id=?",
        (json.dumps(payload, ensure_ascii=False), aid),
    )
    if commit and (
        not bool(getattr(self.conn, "_commit_suspended", False))
        and int(getattr(self.conn, "_atomic_depth", 0) or 0) == 0
    ):
        self.conn.commit()

def _provenance_from_stored(value: object) -> Provenance:
    """从 ctx 持久值还原 Provenance（#146 恢复路）：兼容 Provenance 实例、已存的字符串值、
    历史误序列化的 'Provenance.<name>' 字面串、及非法/缺失值。非法/缺失回落 system_simulation。

    防静默丢源（Sourcery + gemini + coderabbit #175 concur）：Provenance 是 (str, Enum)，
    若曾把枚举实例 str() 落库会得到 'Provenance.player_decree'（而非值 'player_decree'），
    Provenance(...) 不匹配 → ValueError → 丢源退回 system_simulation。故分三层：
    ① 实例直接返回；② 纯值走 Provenance(value)；③ 'Provenance.<name>' 旧脏串剥前缀按成员名查回；
    仍无法识别才回落 system_simulation。"""
    if isinstance(value, Provenance):
        return value
    text = str(value or "system_simulation")
    try:
        return Provenance(text)
    except ValueError:
        pass
    # 历史误序列化：str(枚举实例) 落库的 'Provenance.player_decree' 脏串——剥前缀按成员名查回，
    # 不让旧档玩家来源静默退化成 system_simulation。
    if text.startswith("Provenance."):
        try:
            return Provenance[text.split(".", 1)[1]]
        except KeyError:
            pass
    return Provenance.system_simulation

def latest_error_pack_for_turn(db_path: object, turn: int) -> Optional[str]:
    """同 DB + turn 最新完整错误包绝对路径；无则 None（ADR 0008 决定 7 恢复面）。

    身份取 manifest.db_path + turn，
    禁跨存档串包（同 user-data 下另一 DB 的更高 attempt 不得入选）。
    目录扫描/条目 stat 的 OSError 视为无诊断包——不得拖垮 settling 恢复面。
    """
    root = error_packs_root()
    try:
        if not root.exists():
            return None
        entries = list(root.iterdir())
    except OSError:
        return None
    expected_db_path = str(db_path)
    prefix = f"turn{int(turn)}_attempt"
    best: Optional[Path] = None
    best_n = -1
    for path in entries:
        try:
            if not (path.is_dir() and path.name.startswith(prefix)):
                continue
            n = int(path.name[len(prefix):])
        except (OSError, ValueError):
            continue
        manifest = _read_complete_pack_manifest(path)
        if manifest is None:
            continue
        if (
            str(manifest.get("db_path")) != expected_db_path
            or manifest.get("turn") != int(turn)
        ):
            continue
        if n > best_n:
            best_n = n
            best = path
    if best is None:
        return None
    try:
        return str(best.resolve())
    except OSError:
        return None

def _commitment_bar_value(progress: Dict[str, object]) -> Optional[int]:
    if "remaining_arrears" not in progress:
        return None
    paid = max(0, int(progress.get("paid_total") or 0))
    try:
        remaining = max(0.0, float(progress.get("remaining_arrears") or 0))
    except (TypeError, ValueError):
        remaining = 0.0
    total = paid + remaining
    if total <= 0:
        return 100
    return max(0, min(100, int(round(paid * 100 / total))))

