    if not base.exists():
        return []
    if base.is_file():
        return [str(base.relative_to(root_r)).replace("\\", "/")]
    out: List[str] = []
    for item in sorted(base.rglob("*")):
        if item.is_file():
            out.append(str(item.relative_to(root_r)).replace("\\", "/"))
    return out

def normalize_title_kind(value: object) -> str:
    """Normalize ADR 0009 title-kind values used for active normalization."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    if raw in PERSON_TITLE_KINDS:
        return raw
    if raw in PERSON_IDENTITY_TITLES:
        return "身名分"
    return ""

def prune_auto_saves(saves_dir: str, campaign_id: str, keep_turns: int = AUTO_SAVE_KEEP_TURNS) -> None:
    """清理自动存档：只清同一个 campaign_id，按 turn 分组，绝不碰手动存档。"""
    import os as _os
    import re as _re

    if not _os.path.isdir(saves_dir):
        return
    legacy_auto = _re.compile(rf"^{_re.escape(AUTO_SAVE_PREFIX)}\d{{4}}_\d{{2}}_t\d{{4}}_.+\.db$")
    for f in _os.listdir(saves_dir):
        if legacy_auto.match(f):
            try:
                _os.remove(_os.path.join(saves_dir, f))
            except OSError:
                pass
    campaign_id = (campaign_id or "").strip()
    if not campaign_id:
        return
    buckets: Dict[int, List[str]] = {}
    for f in _os.listdir(saves_dir):
        if not (f.startswith(f"{AUTO_SAVE_PREFIX}{campaign_id}_") and f.endswith(".db")):
            continue
        m = _re.search(r"_t(\d+)_", f)
        if not m:
            continue
        buckets.setdefault(int(m.group(1)), []).append(f)
    keep = max(1, int(keep_turns or 1))
    keep_turn_nums = set(sorted(buckets.keys(), reverse=True)[:keep])
    for turn_num, files in buckets.items():
        if turn_num in keep_turn_nums:
            continue
        for stale in files:
            try:
                _os.remove(_os.path.join(saves_dir, stale))
            except OSError:
                pass

def denunciation_case_upgraded(
    previous_payload: Mapping[str, object] | None,
    fork_state: Mapping[str, object],
) -> bool:
    """案情升级：新分叉或新旨外恶果 → 同人同案可再落（去重键例外）。"""
    prev = previous_payload if isinstance(previous_payload, Mapping) else {}
    prev_exp = prev.get("fork_exposure")
    if not isinstance(prev_exp, Mapping):
        prev_exp = {}
    cur_count = int(fork_state.get("actual_effect_count") or 0)
    prev_count = int(
        prev_exp.get("actual_effect_count")
        if prev_exp.get("actual_effect_count") is not None
        else prev.get("actual_effect_count") or 0
    )
    if cur_count > prev_count:
        return True
    cur_beyond = bool(fork_state.get("beyond_intent"))
    prev_beyond = bool(
        prev_exp.get("beyond_intent")
        if "beyond_intent" in prev_exp
        else prev.get("beyond_intent")
    )
    if cur_beyond and not prev_beyond:
        return True
    cur_fork = bool(fork_state.get("fork"))
    prev_fork = bool(prev.get("fork"))
    if cur_fork and not prev_fork:
        return True
    return False

