def _apply_military_order_office_effect(
    self, state, payload, *, actor: str, reason: str, origin_ref: str,
    content=None,
) -> None:
    """军令职守面：payload.office / office_changes → 人物变更唯一核。"""
    office_items: List[Dict[str, object]] = []
    raw_changes = payload.get("office_changes")
    if isinstance(raw_changes, list):
        for raw in raw_changes:
            if isinstance(raw, dict):
                office_items.append(dict(raw))
    office_title = str(payload.get("office") or "").strip()
    if office_title and actor:
        if not any(
            str(i.get("name") or "").strip() == actor
            and str(i.get("new_office") or i.get("office") or "").strip()
            for i in office_items
        ):
            office_item: Dict[str, object] = {
                "name": actor,
                "动作": "调任",
                "new_office": office_title,
                "office": office_title,
                "reason": reason,
            }
            # Preserve typed 任所 from dossier/pending payload; do not invent.
            seat = str(
                payload.get("region_id")
                or payload.get("任所")
                or payload.get("辖区")
                or ""
            ).strip()
            if seat:
                office_item["region_id"] = seat
            office_items.append(office_item)
    if not office_items:
        return
    from ming_sim.issues import _apply_person_changes
    prepared: List[Dict[str, object]] = []
    for item in office_items:
        entry = dict(item)
        entry.setdefault("origin_ref", origin_ref)
        entry.setdefault("动作", "调任")
        if not entry.get("new_office") and entry.get("office"):
            entry["new_office"] = entry["office"]
        prepared.append(entry)
    results = _apply_person_changes(
        self,
        state,
        prepared,
        content=content,
        origin_ref=origin_ref,
        require_origin=True,
        external_transaction=True,
    )
    accepted_p = [
        r for r in results
        if isinstance(r, dict) and not r.get("rejected")
    ]
    if not accepted_p:
        fail_reason = ""
        if results and isinstance(results[0], dict):
            fail_reason = str(results[0].get("reason") or "")
        raise ValueError(fail_reason or "军令职守变更物化失败")

def _coerce_positive_message_ids(
    self, message_ids: Optional[Iterable[Any]] = None,
) -> List[int]:
    """Normalize chat_message id pins to a stable unique positive list."""
    out: List[int] = []
    seen: set = set()
    for raw in message_ids or ():
        try:
            mid = int(raw)
        except (TypeError, ValueError):
            continue
        if mid > 0 and mid not in seen:
            seen.add(mid)
            out.append(mid)
    return out

def _maybe_write_backing_betray_credit(
    self, state, *, target: str, backing_id: int, reason: str,
) -> None:
    """#658：处置成功且目标确为原案非御笔背书人时，经 ADR 0079 写辜负。

    origin 回指原 dossier。无 backing / 非站台者 / 御笔背书 → 零信用事件。
    """
    if int(backing_id or 0) <= 0:
        return
    person = str(target or "").strip()
    if not person:
        return
    endorsements = self.list_dossier_endorsements(int(backing_id))
    hit = False
    for item in endorsements:
        if bool(item.get("imperial")):
            continue
        if str(item.get("form") or "") != "当面站台":
            continue
        if str(item.get("endorser_id") or "").strip() == person:
            hit = True
            break
    if not hit:
        return
    context = str(reason or "") or "处置站台者"
    from ming_sim.credit_events import KIND_BETRAY, write_credit_event
    write_credit_event(
        self, state,
        person=person,
        event_kind=KIND_BETRAY,
        context=context,
        origin=f"dossier:{int(backing_id)}",
    )

def _participant_roster_tables(self) -> List[tuple[str, set[str]]]:
    """List durable user tables that expose the common roster column."""
    tables = self.conn.execute(
        "SELECT name FROM sqlite_master WHERE type IN ('table', 'view') "
        "AND name NOT LIKE 'sqlite_%' ORDER BY name"
    ).fetchall()
    result: List[tuple[str, set[str]]] = []
    for row in tables:
        table = str(row["name"])
        if table in {"character_knowledge_sources", "decree_dossiers"}:
            continue
        columns = {
            str(column["name"])
            for column in self.conn.execute(
                "PRAGMA table_info(\"" + table.replace('"', '""') + "\")"
            ).fetchall()
        }
        if "participant_roster" in columns:
            result.append((table, columns))
    return result

def effect_origin_rejection(self, origin_ref: str) -> Dict[str, object] | None:
    """Authorize extractor provenance immediately before a durable write.

    When apply_score_extraction arms ``_batch_authorized_open_affair_ids``,
    ``affair:<id>`` must also sit in that frozen batch set — one authority
    for every durable-effect carrier (fiscal included).
    """
    value = str(origin_ref or "").strip()
    valid = value == "盘面自发"
    unauthorized_batch = False
    if value.startswith("dossier:"):
        try:
            dossier_id = int(value.split(":", 1)[1])
            valid = dossier_id > 0 and self.get_decree_dossier(dossier_id) is not None \
                and self.dossier_authorizes_effects(dossier_id)
        except (OverflowError, TypeError, ValueError):
            valid = False
    elif value.startswith("affair:"):
        try:
            from ming_sim.entities.affair.store import (
                UnauthorizedAffairOriginRef,
                parse_origin_ref,
            )
            kind, affair_id = parse_origin_ref(value)
            if kind == "affair" and affair_id is not None:
                self.affairs.get(int(affair_id))
                authorized = getattr(self, "_batch_authorized_open_affair_ids", None)
                if authorized is not None and affair_id not in authorized:
                    valid = False
                    unauthorized_batch = True
                else:
                    valid = True
            else:
                valid = False
        except (KeyError, OverflowError, TypeError, ValueError):
            valid = False
    if valid:
        return None
    if unauthorized_batch:
        from ming_sim.entities.affair.store import UnauthorizedAffairOriginRef
        return {
            "rejected": True,
            # Distinct from missing/invalid existence — strategic preflight
            # must not envelope-fail this; apply paths still reject itemwise.
            "category": "unauthorized_affair_origin",
            "reason": str(UnauthorizedAffairOriginRef()),
        }
    return {
        "rejected": True,
        "category": "missing_origin_ref" if not value else "invalid_origin_ref",
        "reason": ("效果缺 origin_ref；盘面自然演化须显式标为「盘面自发」"
                   if not value else f"origin_ref 非法：{value}"),
    }

def next_pool_portrait_id(self, prefix: str = "minister_pool_") -> str:
    """分配下一个预设头像 ID（顺序递增，不循环）。
    minister_pool: 60 个槽；consort_pool: 20 个槽。
    实际可用槽位 = web/public/portraits/<prefix><N>.png 真存在的编号集合（中途删图会跳过缺号）。
    发行包只带 web/dist；public 不存在时回退扫 web/dist/portraits。
    全部用完后再回退到递增（前端 onError fallback 占位符）。"""
    rows = self.conn.execute(
        "SELECT portrait_id FROM characters WHERE portrait_id LIKE ?",
        (prefix + "%",),
    ).fetchall()
    used = set()
    for r in rows:
        try:
            used.add(int(r["portrait_id"].replace(prefix, "")))
        except ValueError:
            pass
    # 扫真实存在的图编号：源码优先 public；发行包只带 Vite 产物 dist。
    from pathlib import Path
    from ming_sim.paths import bundled_path
    available: set[int] = set()
    for portraits_dir in (
        Path(bundled_path("web", "public", "portraits")),
        Path(bundled_path("web", "dist", "portraits")),
    ):
        if not portraits_dir.is_dir():
            continue
        for p in portraits_dir.glob(f"{prefix}*.png"):
            suffix = p.stem[len(prefix):]
            if suffix.isdigit():
                available.add(int(suffix))
        if available:
            break
    free = sorted(available - used)
    if free:
        return f"{prefix}{free[0]}"
    # 真实图全用完：递增分配，但跳过已知中途缺号（如手动删过的 consort_pool_14）。
    # 编号上限：available 最大值 + 缺号集；超出后继续递增（前端 onError fallback 占位符）。
    max_known = max(available, default=0)
    missing = {n for n in range(1, max_known + 1) if n not in available}
    n = 1
    while n in used or n in missing:
        n += 1
    return f"{prefix}{n}"

def _dispatch_promises(
    db: Any, state: Any, raw: object, *, night_id: int,
    chat_turn_id: int, source: Provenance,
    preexisting_pending_ids: set[int],
) -> SectionResult:
    from ming_sim.strict_types import strict_int

    items, rejected = _section_items(raw, label="应允/拒绝/修改声明", source=source)
    applied: List[Any] = []
    for item in items:
        try:
            # Strict positive int only — bool/float/numeric strings must not
            # coerce via bare int() into another night's pending id.
            action_id = strict_int(
                item.get("action_id"), accept_numeric_strings=False,
            )
        except (TypeError, ValueError):
            action_id = 0
        decision = str(item.get("decision") or "").strip()
        if action_id <= 0 or decision not in {"应允", "拒绝", "修改", "留中"}:
            _reject(
                rejected, item, "判词声明须含正 action_id 与 应允/拒绝/修改/留中",
                "invalid_shape", source,
            )
            continue
        # 只认本夜（或本次无夜上下文）暂存清单里的动作：id 真实存在但挂在
        # 另一夜，声明也不得应允/拒绝它——同样按「不存在实体」拒收（不静默
        # 误批，也不当真拒收物理删除他夜暂存）。
        row = db.conn.execute(
            "SELECT night_id, kind, action, minister_name, night_approved, payload_json FROM pending_actions "
            "WHERE id=? AND turn=? AND status='pending'",
            (action_id, int(state.turn)),
        ).fetchone()
        if (
            row is None or action_id not in preexisting_pending_ids
            or int(row["night_id"] or 0) != int(night_id)
        ):
            _reject(
                rejected, item, f"暂存动作不属本夜暂存清单：{action_id}",
                "missing_ref", source,
            )
            continue
        kind = str(row["kind"] or "")
        action = str(row["action"] or "")
        declared_mode = item.get("mode")
        if declared_mode is not None and (
            kind != "directive" or decision != "应允"
            or not isinstance(declared_mode, str)
            or declared_mode not in {"ordinary", "midzhi"}
        ):
            _reject(rejected, item, "应允模式仅可指定普通/中旨拟旨", "invalid_shape", source)
            continue
        applied_row: Dict[str, Any] = {
            "action_id": action_id, "decision": decision, "kind": kind, "action": action,
        }
        if decision == "留中":
            if kind != "directive":
                _reject(rejected, item, "仅拟旨候选可留中", "invalid_shape", source)
                continue
            db.hold_over_pending_actions(
                int(state.turn), str(row["minister_name"]), [action_id],
            )
        elif decision == "修改":
            new_content = item.get("new_content")
            if (
                kind != "secret_order" or action != "新建"
                or not isinstance(new_content, str) or not new_content.strip()
            ):
                _reject(rejected, item, "只有新建密令可用非空 typed new_content 修改", "invalid_shape", source)
                continue
            payload = json.loads(row["payload_json"] or "{}")
            if not isinstance(payload, dict):
                raise ValueError("密令候选载荷损坏")
            payload["content"] = new_content
            db.conn.execute(
                "UPDATE pending_actions SET payload_json=?, night_approved=0 WHERE id=?",
                (json.dumps(payload, ensure_ascii=False), action_id),
            )
        elif decision == "应允":
            # ADR 0038：密令应允即落地（夜内直写白名单）；任免/拟旨只标

def forecast_text_for(self, decree_ref: str) -> str:
    """问前段文。已结算行仍保留，续推只读，不重推、不重落。"""
    ref = str(decree_ref or "").strip()
    if not ref:
        return ""
    rows = self._conn.execute(
        "SELECT forecast_text FROM staged_declarations "
        "WHERE decree_ref=? AND status!='discarded' "
        "AND forecast_text IS NOT NULL ORDER BY id",
        (ref,),
    ).fetchall()
    parts = [
        str(row["forecast_text"])
        for row in rows
    ]
    return "\n".join(parts)

def _next_attempt(turn: int) -> int:
    """同 turn 的下一个 attempt 序号：既有目录数字后缀 max+1（决定 5，不从 DB 取）。

    len+1 在非连续目录（玩家发包后删过早期 attempt）下会撞既有名而静默覆盖诊断孤本；
    不可解析的后缀忽略。
    """
    root = error_packs_root()
    if not root.exists():
        return 1
    prefix = f"turn{int(turn)}_attempt"
    highest = 0
    for p in root.iterdir():
        if not (p.is_dir() and p.name.startswith(prefix)):
            continue
        try:
            highest = max(highest, int(p.name[len(prefix):]))
        except ValueError:
            continue
    return highest + 1

def project_character_factions(db: Any) -> Dict[str, str]:
    """canonical 党籍投影（庭裁 r1 F1，纯投影、不持久化任何映射表）。

    characters.faction ∩ factions 表现存派系集合：命中者入映射；表外党籍
    （中宫/后金/嫔妃等真实种子）与皇帝节点不入。每次现算——党籍/派系集合
    随引擎演化，投影永远对表当前态。"""
    in_table = {
        row["name"] for row in db.conn.execute("SELECT name FROM factions").fetchall()
    }
    projection: Dict[str, str] = {}
    for row in db.conn.execute("SELECT name, faction FROM characters").fetchall():
        faction = row["faction"]
        if faction in in_table:
            projection[row["name"]] = faction
    return projection

def _fixed_flow_scalars_are_numeric(region_id: str, fiscal: dict) -> bool:
    for key in _FIXED_FLOW_NUMERIC_FIELDS:
        if key not in fiscal:
            continue
        value = fiscal[key]
        try:
            finite_number = (
                not isinstance(value, bool)
                and isinstance(value, (int, float))
                and math.isfinite(float(value))
            )
        except OverflowError:
            finite_number = False
        if not finite_number:
            tlog(f"[province-fiscal] {region_id} fiscal.{key} 非数字，本{TURN_UNIT}固定税收出列")
            return False
    return True

def _commitment_arrears_gate_army_ids(row: sqlite3.Row) -> List[str]:
    ids: List[str] = []
    for key in _commitment_stop_gate(row):
        text = str(key)
        match = re.fullmatch(r"army\.([^.]+)\.arrears(?:\.sum)?", text)
        if not match:
            continue
        for army_id in match.group(1).split("|"):
            army_id = army_id.strip()
            if army_id and army_id not in ids:
                ids.append(army_id)
    return ids

def _fiscal_levy_share_seed(
    meta: Dict[str, object],
