def _preflight_declared_event_groups(
    db: GameDB, state: GameState, groups: dict[str, list[dict]],
) -> dict[str, str]:
    content = db.content
    candidates = {event.id for event in gather_candidate_events(state, db)}
    rejected: dict[str, str] = {}
    pseudo_event = Event(id="season", title="月末整体推演", kind="月末", summary="",
                         urgency=0, severity=0, credibility=100, interests=[], audiences=[])
    for event_id, group in groups.items():
        event = content.event_by_id.get(event_id)
        if event is None:
            rejected[event_id] = f"效果归属的事件不存在：{event_id}"
            continue
        # #1892：三饷请旨的亲裁结局与战略节点信封不同路——它不要求世界状态主账结果
        # （三饷的征收由饷率通道按终局标签核算），只要求标签落在事件自声明的封闭集内，
        # 且事件账里已有请旨答复、终态仍空。归一失败响亮失败（ADR 0014），不静默丢弃亲裁。
        if getattr(event, "category", "") == FISCAL_LEVY_EVENT_CATEGORY:
            if not petition_outcome_is_admissible(state, db, event_id, content):
                rejected[event_id] = f"三饷事项当前不能由亲裁置定结局：{event_id}"
                continue
            outcome: Dict[str, object] = {}
            for item in group:
                _merge_first_event_outcome(outcome, item.get("事件结局") or {}, event_id)
            raw_label = _event_outcome_label(outcome, event_id)
            if not raw_label:
                # 留中／未答毕：本疏已答而事件未终，不写终态（合法，不是缺项）。
                continue
            _fiscal_levy_normalized_terminal_reason_or_abort(event, raw_label, state)
            continue
        if not _is_strategic_foreign_node_event(event):
            rejected[event_id] = f"效果归属的战略事件不存在：{event_id}"
            continue
        if event_id not in candidates or db.event_terminal_state(event_id) or event.auto_trigger:
            rejected[event_id] = f"战略事件当前不能触发：{event_id}"
            continue
        if not any(
            isinstance(issue, dict)
            and str(issue.get("origin_kind") or "").lower() == "event_pool"
            and str(issue.get("id") or issue.get("origin_ref") or "").strip() == event_id
            for item in group for issue in (item.get("new_issues") or [])
        ):
            rejected[event_id] = f"战略事件缺 event_pool 声明：{event_id}"
            continue
        outcome = {}
        for item in group:
            _merge_first_event_outcome(outcome, item.get("事件结局") or {}, event_id)
        label, error = _strategic_event_outcome_label_or_error(event_id, {"事件结局": outcome}, content)
        if error:
            rejected[event_id] = error
            continue
        region_items = [(key, value) for item in group for key, value in (item.get("region_delta") or {}).items()]
        army_items = [(key, value) for item in group for key, value in (item.get("army_delta") or {}).items()]
        power_items = [(key, value) for item in group for key, value in (item.get("power_updates") or {}).items()]
        people = _canonicalize_person_change_names(
            [person for item in group for person in (item.get("人物变更") or [])], content, db,
        )
        new_armies = [army for item in group for army in (item.get("new_armies") or [])]
        if _pending_person_changes_block_event_gate(event, people, db, content=content):
            rejected[event_id] = f"战略事件被同项人物变更阻断：{event_id}"
            continue
        if not (region_items or army_items or power_items or people or new_armies):
            rejected[event_id] = f"战略事件缺世界状态主账结果：{event_id}"
            continue
        error = _strategic_event_result_preflight_error(
            db, state, event_id, event.title, label, dict(region_items), dict(army_items),
            dict(power_items), people, new_armies, content, db.llm_config, pseudo_event,
            ordered_region_items=region_items, ordered_army_items=army_items,
            ordered_power_items=power_items,
        )
        if error:
            rejected[event_id] = error
    return rejected

def neutralize_covert_fiscal_effects(
    db: Any, state: Any, *, exposed_dossier_id: int, prohibition_dossier_id: int,
) -> int:
    """Undo one old case's beyond-intent fiscal contribution, once per live incarnation."""
    old_origin = f"dossier:{int(exposed_dossier_id)}"
    receipt_origin = f"dossier:{int(prohibition_dossier_id)}"
    rows = db.list_fiscal_effects_for_dossier(int(exposed_dossier_id))
    raw_keys = {str(row.get("key") or "").strip() for row in rows if row.get("beyond_intent")}
    keys: set[str] = set()
    for raw_key in raw_keys:
        stem = db._stem_of(raw_key)
        if not stem:
            continue
        if raw_key.endswith(("_base", "_rate")):
            keys.add(raw_key)
        else:
            keys.add(f"{stem}_base")

    written = 0
    for key in sorted(keys):
        stem = db._stem_of(key)
        base_key, rate_key = f"{stem}_base", f"{stem}_rate"
        receipt = db.conn.execute(
            """SELECT 1 FROM fiscal_config_changes
               WHERE origin_ref=? AND key=? AND reason=? LIMIT 1""",
            (receipt_origin, key, _COVERT_NEUTRALIZATION_REASON),
        ).fetchone()
        if receipt is None:
            receipt = db.conn.execute(
                """SELECT 1 FROM fiscal_config_tombstones
                   WHERE origin_ref=? AND key IN (?, ?) AND reason=? LIMIT 1""",
                (receipt_origin, base_key, rate_key, _COVERT_NEUTRALIZATION_REASON),
            ).fetchone()
        if receipt is not None:
            continue

        current = db.get_fiscal_config().get(key)
        if current is None:
            continue
        latest_remove = db.conn.execute(
            "SELECT removed_turn turn,id FROM fiscal_config_tombstones WHERE key=? ORDER BY removed_turn DESC,id DESC LIMIT 1",
            (key,),
        ).fetchone()
        latest_create = db.conn.execute(
            "SELECT turn,id,origin_ref,beyond_intent FROM fiscal_config_creations WHERE key=? ORDER BY turn DESC,id DESC LIMIT 1",
            (key,),
        ).fetchone()
        remove_mark = (int(latest_remove["turn"]), 0, int(latest_remove["id"])) if latest_remove else (-1, -1, -1)
        create_mark = (int(latest_create["turn"]), 1, int(latest_create["id"])) if latest_create else (-1, -1, -1)
        start = max(remove_mark, create_mark)

        if (
            latest_create is not None and create_mark > remove_mark
            and str(latest_create["origin_ref"]) == old_origin
            and bool(db.coerce_beyond_intent_flag(latest_create["beyond_intent"]))
        ):
            if key != base_key:
                continue
            if db.remove_fiscal_item(
                key, commit=False, origin_ref=receipt_origin,
                reason=_COVERT_NEUTRALIZATION_REASON, turn=int(state.turn),
            ) is not None:
                written += 1
            continue

        contribution = 0
        for row in db.conn.execute(
            """SELECT id,turn,delta,beyond_intent FROM fiscal_config_changes
               WHERE key=? AND origin_ref=? ORDER BY turn,id""",
            (key, old_origin),
        ).fetchall():
            mark = (int(row["turn"]), 2, int(row["id"]))
            if mark > start and bool(db.coerce_beyond_intent_flag(row["beyond_intent"])):
                contribution += int(row["delta"])
        floor = db.fiscal_config_minimum_value(key) or 0
        new_value = max(int(floor), int(current) - max(0, contribution))
        _write_fiscal_config_change(
            db, turn=int(state.turn), key=key, old_value=int(current), new_value=new_value,
            origin_ref=receipt_origin, reason=_COVERT_NEUTRALIZATION_REASON,
        )

def _issue_audience_names(db: Any, issue: Any) -> set[str] | None:
    """Audience-name supplement for an event-origin issue, or ``None`` if N/A.

    ``events.audiences`` names a positive grant onto originating issues; it is
    not an ACL/veto over ``knowledge["issues"]``.  A legitimate empty list is an
    empty supplement.  DB execution errors and JSON/typed-shape malformations
    propagate unchanged.  Content fallback applies only when the events query
    succeeds with no row.
    """
    try:
        origin_kind = str(issue["origin_kind"] or "")
        origin_ref = str(issue["origin_ref"] or "").strip()
    except (KeyError, IndexError, TypeError):
        return None
    if origin_kind != "event_pool":
        return None
    if not origin_ref:
        return set()

    raw: object = None
    saw_db_row = False
    if hasattr(db, "conn"):
        row = db.conn.execute(
            "SELECT audiences FROM events WHERE id=?", (origin_ref,),
        ).fetchone()
        if row is not None:
            saw_db_row = True
            raw = row["audiences"]
    if not saw_db_row:
        content = getattr(db, "content", None)
        event_by_id = getattr(content, "event_by_id", None) or {}
        ev = event_by_id.get(origin_ref)
        if ev is None:
            return set()
        raw = getattr(ev, "audiences", None)

    if isinstance(raw, str):
        raw = json.loads(raw)
    if not isinstance(raw, list):
        raise TypeError(
            f"event {origin_ref!r} audiences must be a list[str], got {type(raw).__name__}"
        )
    names: set[str] = set()
    for idx, name in enumerate(raw):
        if not isinstance(name, str):
            raise TypeError(
                f"event {origin_ref!r} audiences[{idx}] must be str, "
                f"got {type(name).__name__}"
            )
        stripped = name.strip()
        if stripped:
            names.add(stripped)
    return names

def legacy_reasoning_strength(data: Dict[str, object]) -> str:
    candidates = []
    if str(data.get("advanced_model") or "").strip():
        candidates.append(data.get("advanced_thinking_level"))
    candidates.append(data.get("thinking_level"))
    for value in candidates:
        legacy = str(value or "").strip().lower()
        if legacy in {"minimal", "disabled", "none"}:
            return "off"
        strength = normalize_reasoning_strength(legacy)
        if strength:
            return strength
    return ""

def _require_agno() -> None:
    from packaging.requirements import Requirement
    from packaging.utils import canonicalize_name
    from packaging.version import Version
    from ming_sim.constants import ROOT_DIR

    for raw in Path(ROOT_DIR, "requirements.txt").read_text(encoding="utf-8").splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        req = Requirement(line)
        if canonicalize_name(req.name) != "agno":
            continue
        installed = installed_distribution_version(req.name)
        if Version(installed) not in req.specifier:
            raise DependencyMismatch(
                f"installed {req.name} {installed} does not satisfy {line}",
                package=req.name,
                requirement=line,
            )
        return
    raise DependencyMismatch(
        "requirements.txt has no declaration for agno",
        package="agno",
        requirement="",
    )

def character_office_archive_text(db: Any, state: Any, character: Any, knowledge: dict) -> str:
    """本衙门公事档案：职位底账 + 可见案卷。与目录 公事档案.txt 同一份。"""
    from ming_sim.decree_vocabulary import render_referenceable_dossier_brief

    name = str(getattr(character, "name", "") or "")
    world = dict(knowledge.get("world") or {})
    office_lines = [
        f"{key}：{value}"
        for key, value in world.items()
        if key in _LEDGER_KEYS and str(value or "").strip()
    ]
    if hasattr(db, "list_referenceable_dossiers"):
        brief = render_referenceable_dossier_brief(
            db.list_referenceable_dossiers(name, state.turn),
        )
        if brief:
            office_lines.append(brief)
    return "\n".join(office_lines) or "（无）"

def _consume_rescript_answers(
    session: Any, chain: Dict[str, Any], *, source: Provenance,
) -> None:
    """把已裁批红接回案卷 / 请旨续推；幂等，已落不动。

    同一旨 / 同一世界段多问须全部答完才续推一次（ADR 0157 步骤 4）。
    """
    db, state = session.db, session.state
    turn = int(state.turn)
    from ming_sim.rescript_draft import consume_memorial_answers
    consume_memorial_answers(session, chain, source=source)
    rows = db.list_pending_decisions(turn)
    decided = [r for r in rows if str(r.get("status") or "") == "decided"]
    if not decided:
        return

    def _answer_from_row(row: Dict[str, object]) -> Dict[str, object]:
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        return {
            **row, "choice": dict(choice),
            "label": str(choice.get("label") or ""),
            "hint": str(choice.get("hint") or ""),
            "note": str(choice.get("note") or ""),
            "context": str(row.get("context") or ""),
            "event_id": str(row.get("event_id") or ""),
            "title": str(row.get("title") or ""),
        }

    for row in decided:
        event_id = str(row.get("event_id") or "")
        if event_id.startswith("deliberation:"):
            from ming_sim.rescript_actions import apply_imperial_deliberation_push
